"""Organise the review's research-question answers question-first.

``protocol.research_questions`` — declared alongside PICO and the eligibility
criteria — is asked of every included study, and each answer is charted into
``DataChartingRubric.custom_fields`` (keyed by the question's id when it has
one). ``protocol.charting_questions``, the older plain-string list, lands in the
same place and is handled identically here.

That is the right *storage*, but on its
own it is unreadable: the Markdown carries all of a study's answers inside one
narrative-table cell (23,000 characters wide in a 23-question review), the JSON
has them only as an unlabelled dict per study, and the RDF has them not at all.
A reader who wants "what did every study say about validation strategy?" has to
reconstruct it by hand from any of the three.

So every export pivots them:

* **Markdown** (:func:`merge_markdown`) — an appendix, one section per
  question, listing every study's answer; the oversized narrative-table cells
  become a cross-reference to it.
* **JSON** (:func:`merge_json`) — a top-level ``research_questions`` block
  (question text, theme, and every study's answer with its source id / pmid /
  title / year).
* **RDF** (:func:`add_to_graph`) — a ``slr:ResearchQuestion`` node per question
  under a stable IRI, linked to the review (``slr:has_research_question``) and to
  each answer (``slr:has_answer`` / ``slr:answers_question`` /
  ``slr:about_source``), so a question is queryable without string-matching an
  id inside a literal.

This runs for **every** review — the hosted pipeline's own searches as much as
a bring-your-own-corpus run — because it hangs off the exporters in
``synthscholar.export`` and ``synthscholar.ontology.rdf_export`` rather than
off any one entry point. Where the articles came from is irrelevant to it; only
``data_charting_rubrics`` is.

The per-study ``custom_fields`` are left untouched — this adds a second view of
the same data, it never moves it. ``research_questions`` is deliberately *not*
a ``PRISMAReviewResult`` field: Pydantic drops it on re-validation, so
re-exporting regenerates the block from the rubrics and they stay the single
source of truth.

Every merge is idempotent — applying it to an already-merged document replaces
the previous view rather than stacking a second copy.
"""
from __future__ import annotations

import json
import re
from typing import TYPE_CHECKING, Any

if TYPE_CHECKING:  # pragma: no cover
    from rdflib import Graph, URIRef

    from synthscholar.models import PRISMAReviewResult

APPENDIX_TITLE = "Research-Question Charting"

# A leading question id: "RQ1.1", "[RQ1.1]", "Q3", "SQ2.4 —", "RQ 1.1:" …
_ID_RE = re.compile(r"^\s*[\[(]?\s*((?:RQ|SQ|Q)\s*\d+(?:[.\-]\d+)*)\s*[\])]?\s*[:.\-–—)]*\s*",
                    re.IGNORECASE)
# Split a Markdown table row on pipes the exporter did not escape.
_PIPE_RE = re.compile(r"(?<!\\)\|")
_APPENDIX_RE = re.compile(r"^## Appendix ([A-Z])(?::\s*(.*))?$")
_FOOTER_PREFIX = "*Generated by SynthScholar"

# Cells longer than this in the narrative table's Review Q&A column become a
# pointer to the appendix. Shorter ones stay inline — a two-question review is
# perfectly readable in place.
CELL_CROSSREF_THRESHOLD = 400


# ── the index ─────────────────────────────────────────────────────────────────

def _norm(s: str) -> str:
    return re.sub(r"\s+", " ", (s or "").strip().lower())


def _split_id(text: str) -> tuple[str, str]:
    """Return ``(question_id, remaining_text)`` for *text*; id is "" if absent."""
    m = _ID_RE.match(text or "")
    if not m:
        return "", (text or "").strip()
    qid = re.sub(r"\s+", "", m.group(1)).upper()
    return qid, (text or "")[m.end():].strip()


def _slug(text: str) -> str:
    """An IRI-safe identifier for a question the protocol wrote as plain text."""
    s = re.sub(r"[^a-z0-9]+", "-", (text or "").lower()).strip("-")
    return s[:60].rstrip("-") or "question"


def _major(qid: str) -> str:
    """"RQ1.1" → "RQ1" — the theme group a question belongs to."""
    m = re.match(r"^([A-Z]+\d+)", qid or "")
    return m.group(1) if m else ""


def _short_title(question_text: str) -> str:
    """A section label for the question.

    Honours the common ``"Short title: full question?"`` form when the protocol
    uses it; otherwise takes the leading clause, truncated on a word boundary.
    """
    text = (question_text or "").strip()
    head, sep, rest = text.partition(":")
    if sep and rest.strip() and len(head) <= 80 and "?" not in head:
        return head.strip().rstrip(".")
    clause = re.split(r"[?:—–]", text, maxsplit=1)[0].strip().rstrip(".,;")
    if len(clause) <= 70:
        return clause
    return f"{clause[:70].rsplit(' ', 1)[0]}…"


def _article_for(rubric, articles: list, index: int, by_doi: dict, by_title: dict):
    """Resolve the ``Article`` a charting rubric describes.

    DOI first, then title, then position — the rubrics are generated per
    included article in order, so the positional fallback is exact for anything
    the pipeline produces and only a guess for a hand-assembled result with
    neither a DOI nor a matching title.
    """
    art = by_doi.get(_norm(getattr(rubric, "doi", "")))
    if art is None:
        art = by_title.get(_norm(getattr(rubric, "title", "")))
    if art is None and index < len(articles):
        art = articles[index]
    return art


def build_index(result: "PRISMAReviewResult",
                themes: dict[str, str] | None = None) -> dict[str, Any]:
    """Pivot ``custom_fields`` across all charting rubrics into a question-first index.

    *themes* optionally labels the appendix sections, keyed by question id
    (``"RQ1.1"``) or by its major group (``"RQ1"``); without it the major group
    id is the theme.

    Returns ``{}`` when no rubric carries a custom field — a review with no
    protocol-specific questions gets no appendix and no extra triples.
    """
    themes = {k.upper(): v for k, v in (themes or {}).items()}
    rubrics = list(getattr(result, "data_charting_rubrics", []) or [])
    articles = list(getattr(result, "included_articles", []) or [])
    by_doi = {_norm(a.doi): a for a in articles if getattr(a, "doi", "")}
    by_title = {_norm(a.title): a for a in articles if getattr(a, "title", "")}

    # Protocol order is the review's own order — keep it, and append any key a
    # rubric answered that the protocol never asked for rather than dropping it.
    protocol = getattr(result, "protocol", None)
    declared = list(getattr(protocol, "research_questions", []) or [])
    protocol_questions = list(getattr(protocol, "charting_questions", []) or [])
    order: list[str] = []          # canonical keys, in order
    text_for: dict[str, str] = {}  # canonical key → full question text
    id_for: dict[str, str] = {}    # canonical key → question id ("" if unnumbered)
    slug_for: dict[str, str] = {}  # canonical key → IRI-safe slug
    theme_for: dict[str, str] = {}  # canonical key → theme declared in the protocol
    title_for: dict[str, str] = {}  # canonical key → short title declared there

    def _register(raw: str) -> str:
        qid, rest = _split_id(raw)
        key = qid or _norm(raw)
        if key not in text_for:
            order.append(key)
            text_for[key] = rest or raw.strip()
            id_for[key] = qid
            slug_for[key] = qid or _slug(text_for[key])
        elif rest and len(rest) > len(text_for[key]):
            # A bare "RQ1.1" key in a rubric, then the full text from the
            # protocol (or the reverse) — keep whichever actually says something.
            text_for[key] = rest
        return key

    # Declared research questions first, in protocol order: their id, theme and
    # short title are authoritative — nothing here is inferred from the text.
    for rq in declared:
        if not (rq.question or "").strip():
            continue
        key = _register(f"{rq.question_id} {rq.question}".strip())
        if rq.theme:
            theme_for[key] = rq.theme
        if rq.short_title:
            title_for[key] = rq.short_title
    for q in protocol_questions:
        _register(q)

    answers: dict[str, list[dict[str, str]]] = {}
    for i, rub in enumerate(rubrics):
        custom = dict(getattr(rub, "custom_fields", {}) or {})
        if not custom:
            continue
        art = _article_for(rub, articles, i, by_doi, by_title)
        for raw_key, answer in custom.items():
            if not str(answer).strip():
                continue
            key = _register(str(raw_key))
            answers.setdefault(key, []).append({
                "source_id": rub.source_id or f"S-{i + 1:03d}",
                "pmid": getattr(art, "pmid", "") if art else "",
                "title": rub.title or (getattr(art, "title", "") if art else ""),
                "year": str(rub.year or (getattr(art, "year", "") if art else "")),
                "answer": str(answer).strip(),
            })

    if not answers:
        return {}

    n_total = len(rubrics) or len(articles)
    questions = []
    for key in order:
        if key not in answers:
            continue  # asked in the protocol, answered by nobody
        qid = id_for.get(key, "")
        theme = (themes.get(qid) or themes.get(_major(qid))
                 or theme_for.get(key) or _major(qid))
        questions.append({
            # "" for a question the protocol wrote as plain text; `slug` is what
            # the RDF IRI is minted from either way.
            "question_id": qid,
            "slug": slug_for.get(key, key),
            "theme": theme,
            "short_title": title_for.get(key) or _short_title(text_for.get(key, key)),
            "question_text": text_for.get(key, key),
            "n_studies_charted": len(answers[key]),
            "n_studies_total": n_total,
            "answers": answers[key],
        })

    return {
        "n_questions": len(questions),
        "n_studies": n_total,
        "note": ("Protocol research questions with every included study's charted "
                 "answer. Same content as DataChartingRubric.custom_fields, "
                 "pivoted question-first."),
        "questions": questions,
    }


# ── Markdown ──────────────────────────────────────────────────────────────────

def _anchor(heading: str) -> str:
    slug = re.sub(r"[^a-z0-9\s-]", "", heading.lower())
    return re.sub(r"\s+", "-", slug.strip())


def _appendix_letters(lines: list[str]) -> dict[str, int]:
    """``{letter: line index}`` for every ``## Appendix X`` heading present."""
    return {m.group(1): i for i, line in enumerate(lines)
            if (m := _APPENDIX_RE.match(line.rstrip()))}


def _boundary(lines: list[str], after: int) -> int:
    """Where the appendix ends: the next section heading, or the export footer."""
    for i in range(after + 1, len(lines)):
        if lines[i].startswith("## ") or lines[i].startswith(_FOOTER_PREFIX):
            return i
    return len(lines)


def _walk_back(lines: list[str], idx: int, floor: int = 0) -> int:
    """Skip back over the blank lines and horizontal rule introducing *idx*."""
    while idx > floor and lines[idx - 1].strip() in ("", "---"):
        idx -= 1
    return idx


def _strip_existing_appendix(lines: list[str]) -> tuple[list[str], str | None]:
    """Remove a previously merged research-question appendix; return its letter.

    Together with :func:`merge_markdown`'s insertion rule — section preceded by
    its own rule, inserted where the following section's rule starts — this
    makes a re-merge a fixed point rather than an append.
    """
    start = None
    letter = None
    for i, line in enumerate(lines):
        m = _APPENDIX_RE.match(line.rstrip())
        if m and (m.group(2) or "").strip() == APPENDIX_TITLE:
            start, letter = i, m.group(1)
            break
    if start is None:
        return lines, None
    end = _walk_back(lines, _boundary(lines, start), floor=start)
    return lines[:_walk_back(lines, start)] + lines[end:], letter


def _render_appendix(index: dict[str, Any], letter: str) -> list[str]:
    """The appendix body. Never ends on a blank line — the strip depends on it."""
    out = [f"## Appendix {letter}: {APPENDIX_TITLE}", "",
           f"Every included study's answer to each of the {index['n_questions']} "
           f"protocol research questions, charted from the full text. The same "
           f"content is the `research_questions` block in the JSON export and "
           f"`slr:ResearchQuestion` / `slr:ChartingQuestionAnswer` in the RDF "
           f"export.", ""]
    last_theme = None
    themed = any(q["theme"] for q in index["questions"])
    for q in index["questions"]:
        # An unnumbered question after themed ones would otherwise read as part
        # of the last theme.
        theme = q["theme"] or ("Other charted questions" if themed else "")
        if theme and theme != last_theme:
            out.extend([f"### {theme}", ""])
            last_theme = theme
        title = " — ".join(x for x in (q["question_id"], q["short_title"]) if x)
        out.extend([
            f"#### {title}", "",
            f"**Question.** {q['question_text']}", "",
            f"*{q['n_studies_charted']} of {q['n_studies_total']} included "
            f"studies charted.*", "",
        ])
        for a in q["answers"]:
            label = f"**{a['source_id']}**"
            meta = " — ".join(x for x in (a["title"], a["year"]) if x)
            if meta:
                label += f" — {meta}"
            if a["pmid"]:
                label += f" (`{a['pmid']}`)"
            out.extend([label, "", a["answer"], ""])
    while out and not out[-1].strip():
        out.pop()
    return out


def _crossref_narrative_table(lines: list[str], target: str) -> list[str]:
    """Point the narrative table's oversized Review Q&A cells at the appendix."""
    out = list(lines)
    for i, line in enumerate(out):
        if not (line.startswith("|") and "Review Q&A" in line):
            continue
        header = _PIPE_RE.split(line)[1:-1]
        col = next((j for j, c in enumerate(header) if c.strip() == "Review Q&A"), None)
        if col is None:
            continue
        for k in range(i + 1, len(out)):
            row = out[k]
            if not row.startswith("|"):
                break
            if set(row.replace("|", "").strip()) <= set("- :"):
                continue  # the header separator
            cells = _PIPE_RE.split(row)[1:-1]
            if len(cells) <= col or len(cells[col].strip()) <= CELL_CROSSREF_THRESHOLD:
                continue
            cells[col] = f" {target} "
            out[k] = "|" + "|".join(cells) + "|"
    return out


def merge_markdown(md: str, index: dict[str, Any]) -> str:
    """Add the research-question appendix and cross-reference the narrative table."""
    if not index:
        return md
    lines = md.split("\n")
    lines, previous = _strip_existing_appendix(lines)

    used = _appendix_letters(lines)
    # Reuse the letter a previous merge had, so a re-export doesn't renumber the
    # appendix (and break anyone's link to it).
    letter = previous if previous and previous not in used else next(
        (c for c in "ABCDEFGHIJKLMNOPQRSTUVWXYZ" if c not in used), "Z")

    section = ["", "---", ""] + _render_appendix(index, letter)
    # Slot it into letter order among the existing appendices, so the document
    # doesn't read A, C, B — and place it where the following section's rule
    # starts, so it arrives with exactly one rule above it.
    after = [i for lt, i in sorted(used.items()) if lt > letter]
    if after:
        at = after[0]
    else:
        # Last appendix in the document — before the export's closing footer.
        at = next((i for i, l in enumerate(lines)
                   if l.startswith(_FOOTER_PREFIX)), len(lines))
    lines = lines[:_walk_back(lines, at)] + section + lines[_walk_back(lines, at):]

    heading = f"## Appendix {letter}: {APPENDIX_TITLE}"
    return "\n".join(_crossref_narrative_table(
        lines, f"See [Appendix {letter}](#{_anchor(heading)})"))


# ── JSON ──────────────────────────────────────────────────────────────────────

def merge_json(text: str, index: dict[str, Any]) -> str:
    """Add (or replace) the top-level ``research_questions`` block."""
    if not index:
        return text
    data = json.loads(text)
    data["research_questions"] = index
    return json.dumps(data, indent=2, ensure_ascii=False)


# ── RDF ───────────────────────────────────────────────────────────────────────

def question_uri(review_uri: "str | URIRef", slug: str) -> "URIRef":
    """A stable IRI for a question, under the review that asked it."""
    from rdflib import URIRef

    base = str(review_uri).rstrip("/#")
    sep = ":" if base.startswith("urn:") else "/"
    return URIRef(f"{base}{sep}question{sep}{re.sub(r'[^A-Za-z0-9._-]', '_', slug)}")


def add_to_graph(g: "Graph", index: dict[str, Any], review_uri: "URIRef | None" = None) -> None:
    """Add the question nodes and their answers to an SLR-ontology graph.

    Idempotent: anything a previous call added is removed first, so re-adding to
    a graph parsed back from a merged export doesn't duplicate the questions.
    """
    if not index:
        return

    from rdflib import BNode, Literal, Namespace
    from rdflib.namespace import RDF

    SLR = Namespace("https://w3id.org/slr-ontology/")
    BIBO = Namespace("http://purl.org/ontology/bibo/")
    DCT = Namespace("http://purl.org/dc/terms/")

    for node_type in (SLR.ResearchQuestion, SLR.ChartingQuestionAnswer):
        for node in list(g.subjects(RDF.type, node_type)):
            g.remove((node, None, None))
            g.remove((None, None, node))

    review: Any = review_uri
    if review is None:
        review = next(g.subjects(RDF.type, SLR.SystematicReview), None)
    if review is None:
        return

    # pmid → IncludedSource, so each answer can point at the study it came from.
    src_by_pmid: dict[str, Any] = {}
    for src, pmid in g.subject_objects(BIBO.pmid):
        src_by_pmid.setdefault(str(pmid), src)

    for q in index["questions"]:
        qnode = question_uri(review, q.get("slug") or q["question_id"])
        g.add((qnode, RDF.type, SLR.ResearchQuestion))
        if q["question_id"]:
            g.add((qnode, SLR.question_id, Literal(q["question_id"])))
        g.add((qnode, SLR.question_text, Literal(q["question_text"])))
        if q["short_title"]:
            g.add((qnode, DCT.title, Literal(q["short_title"])))
        if q["theme"]:
            g.add((qnode, SLR.theme, Literal(q["theme"])))
        g.add((review, SLR.has_research_question, qnode))

        for a in q["answers"]:
            ans = BNode()
            g.add((ans, RDF.type, SLR.ChartingQuestionAnswer))
            if q["question_id"]:
                g.add((ans, SLR.question_id, Literal(q["question_id"])))
            g.add((ans, SLR.answer_text, Literal(a["answer"])))
            g.add((ans, SLR.source_id, Literal(a["source_id"])))
            g.add((ans, SLR.answers_question, qnode))
            g.add((qnode, SLR.has_answer, ans))
            src = src_by_pmid.get(a["pmid"])
            if src is not None:
                g.add((ans, SLR.about_source, src))
                # Hang it off the charting record too, so a study-first walk of
                # the graph reaches its answers without going via the question.
                for rec in g.objects(src, SLR.charting_record):
                    g.add((rec, SLR.charting_question_answer, ans))
